export function ChatBubble({
  message = "{{message}}",
  sender = "{{sender}}",
  initials = "{{initials}}",
  timestamp = "{{timestamp}}",
  accent = "{{accent}}",
}) {
  const mine = sender === "me";
  return (
    <div style={{ display: "flex", gap: 10, maxWidth: 320, alignItems: "flex-end", fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430",
      flexDirection: mine ? "row-reverse" : "row", marginLeft: mine ? "auto" : 0 }}>
      <span style={{ width: 32, height: 32, borderRadius: "50%", flexShrink: 0, display: "grid", placeItems: "center", background: accent, color: "#FAF7F2", fontSize: 12, fontWeight: 700 }} aria-hidden="true">{initials}</span>
      <div style={{ background: mine ? accent : "#FAF7F2", border: mine ? "1px solid transparent" : "1px solid #24143020", borderRadius: 14, padding: "10px 14px" }}>
        <p style={{ margin: "0 0 4px" }}>{message}</p>
        <time style={{ display: "block", fontSize: 11, color: mine ? "#241430b0" : "#24143080" }} dateTime="2026-08-18T10:42">{timestamp}</time>
      </div>
    </div>
  );
}
